        SaleBid saleBid = event.saleBid();
        ProductSize productSize = saleBid.getProductSize();
        ProductColor productColor = productSize.getProductColor();
        Long sellerId = saleBid.getSeller().getId();

        String message = String.format("관심 상품 '%s' (사이즈 %s)에 새 판매 입찰이 등록되었습니다. 판매 희망가: %,d원",
                productColor.getProduct().getName(), productSize.getSize(), saleBid.getBidPrice());

        for (Interest interest : interestRepository.findAllByProductColorId(productColor.getId())) {
